            block = self.free_table[block_id]
            heapq.heappush(self.priority_queue,
                          (last_accessed, -block.num_hashed_tokens, block_id))

    def remove(self, block_id: int):
        if block_id not in self.free_table:
            raise ValueError(
                "Attempting to remove block that's not in the evictor")
        # Lazy deletion: just remove from free_table, not from priority_queue
        self.free_table.pop(block_id)

    @property
    def num_blocks(self) -> int:
        return len(self.free_table)

    def _rebuild_priority_queue(self):
        """Rebuild the priority queue from scratch, removing stale entries."""
        self.priority_queue = []
        for block_id, block in self.free_table.items():
            heapq.heappush(
                self.priority_queue,
                (block.last_accessed, -block.num_hashed_tokens, block_id))


def make_evictor(eviction_policy: EvictionPolicy) -> Evictor:
    if eviction_policy == EvictionPolicy.LRU:
        return LRUEvictor()
    else:
        raise ValueError(f"Unknown cache eviction policy: {eviction_policy}")
